@startuml

class Country {
  + Name : string
  + VATRate : float
  + Currency : string
  + ConversionRateToEuro : float
}

class Product {
  + Name : string
  + Description : string
  + NetPrice : double
}

class Manufacturer {
  + Name : string
}

class Representative {
  + FirstName : string
  + LastName : string
  + SSN : int
  + Telephone : string
  + Email : string
}

class Customer {
  + Name : string
  + Address : string
  + Telephone : string
  + Email : string
}

class Order {
  + OrderID : string
  + Quantity : int
  + OrderDate : date
  + DesiredDeliveryDate : date
}

Product "*" -- "1" Manufacturer : manufacturedBy
Product "*" -- "1" Country : availableIn
Representative "1" -- "1" Country : responsibleFor
Customer "*" -- "0..*" Country : resellsIn
Representative "1" -- "*" Order : places
Order "*" -- "1" Product : refersTo
Order "*" -- "1" Customer : placedBy

@enduml

